"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type HoverEffectPrimitiveProps = ComponentProps<typeof motion.div>;

export function HoverEffectPrimitive({ children, ...props }: HoverEffectPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      whileHover={reduceMotion ? undefined : {y: -4,scale: 1.01}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
    >
      {children}
    </motion.div>
  );
}
